import {PAYOUTS,LABELS,unlocked} from './engine.mjs';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(n).toLocaleString(), DAY=86400000;
let data, cardPage=0, serial=0, requestId=0, currentCalculation=null;
const pending=new Map(), worker=new Worker('worker.mjs',{type:'module'});
worker.onmessage=({data:message})=>{const p=pending.get(message.id);if(!p)return;pending.delete(message.id);message.error?p.reject(Error(message.error)):p.resolve(message.result)};
worker.onerror=()=>{for(const p of pending.values())p.reject(Error('The calculator worker could not finish. Reload to try again.'));pending.clear()};
function calculate(kind,input){return new Promise((resolve,reject)=>{const id=++requestId;pending.set(id,{resolve,reject});worker.postMessage({id,kind,input,party:data.party})})}
const names={events:'Events & reset',pinballs:'Pinball simulator',resources:'Resource estimates',cards:'Card album',exchange:'Card Exchange',commands:'Bot commands'};
const icons=n=>data.icons[n]||'🎮';
const date=ms=>new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(ms));
function countdown(ms){let s=Math.max(0,Math.floor(ms/1000)),d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);return `${d?d+'d ':''}${h}h ${m}m ${s%60}s`}
function mod(a,b){return (a%b+b)%b}
function regularAt(now){const c=data.events.regular,day=Math.floor(now/DAY),anchor=Date.parse(c.anchor.date)/DAY,p=mod(day-anchor,c.events.length*c.duration_days),i=Math.floor(p/c.duration_days),start=(day-p%c.duration_days)*DAY;return {name:c.events[i],day:p%c.duration_days+1,start,end:start+c.duration_days*DAY}}
function pvpAt(now){const c=data.events.pvp,block=c.registration_days+c.duration_days,day=Math.floor(now/DAY),anchor=Date.parse(c.anchor.date)/DAY,p=mod(day-anchor,c.events.length*block),i=mod(c.events.indexOf(c.anchor.event)+Math.floor(p/block),c.events.length),position=p%block,start=(day-position+c.registration_days)*DAY;return {name:c.events[i],registration:position<c.registration_days,day:position-c.registration_days+1,registrationDate:(day-position)*DAY,start,end:start+c.duration_days*DAY}}
function heading(title,lead,tag){return `<div class="eyebrow">${tag||'THE CLASH OF CRITTERS TOOLKIT'}</div><h1>${title}</h1><p class="lead">${lead}</p>`}
function eventCard(e,pvp=false){return `<article class="panel"><div class="row between"><span class="event-icon">${icons(e.name)}</span><span class="chip ${e.registration?'purple':'live'}">${e.registration?'REGISTRATION':'DAY '+e.day}</span></div><h2>${esc(e.name)}</h2><div class="small muted">${date(e.registration?e.start:e.start)} – ${date(e.end-DAY)} · UTC</div><div class="countdown" data-countdown="${e.registration?e.start:e.end}"></div><div class="small muted">${e.registration?'Battle begins':'Event ends'} at 00:00 UTC</div>${pvp?`<p class="note">${e.name.startsWith('Gold Rush')||e.name==='Dune Rush'?(e.registration?'Energy Drink slot opens when battle begins.':'Energy Drink slot active · 1 drink per ×1 hit.'):'The direct Energy Drink slot is inactive.'}</p>`:''}</article>`}
function eventsPage(){const now=Date.now(),r=regularAt(now),p=pvpAt(now),nextReset=(Math.floor(now/DAY)+1)*DAY,h=data.horde,pos=mod(now/DAY,1)*86400%h.cycle_seconds,live=pos>=h.rest_seconds,hEnd=now+((live?h.cycle_seconds:h.rest_seconds)-pos)*1000;
 let upcoming=[],t=r.end;for(let i=0;i<5;i++){const event=regularAt(t);upcoming.push(event);t=event.end}
 $('page').innerHTML=heading('Know what’s live.','Events, registration and reset timers, all in one place.','THE CARAVAN NOTICEBOARD')+`<div class="hero-panel"><div><div class="small">NEXT DAILY RESET</div><div class="number" data-countdown="${nextReset}"></div></div><div><strong>00:00 UTC</strong><div class="small muted">Shown in your time: ${new Date(nextReset).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</div></div></div><div class="grid grid3">${eventCard(r)}${eventCard(p,true)}<article class="panel"><div class="row between"><span class="event-icon">👾</span><span class="chip ${live?'live':'purple'}">${live?'LIVE':'SETTLEMENT'}</span></div><h2>Horde Invasion</h2><div class="small muted">1 hour settlement · 3 hours live</div><div class="countdown" data-countdown="${hEnd}"></div><div class="small muted">Until ${live?'settlement':'the next invasion'}</div></article></div><div class="section-head"><h2>Next regular events</h2><span class="chip">3 DAYS PER EVENT</span></div><div class="timeline">${upcoming.map(x=>`<div class="panel"><div class="event-icon">${icons(x.name)}</div><h3>${esc(x.name)}</h3><div class="small muted">${date(x.start)} – ${date(x.end-DAY)}</div></div>`).join('')}</div><div class="section-head"><h2>Next battles</h2></div><div class="grid">${[pvpAt(p.end),pvpAt(p.end+7*DAY)].map(x=>`<div class="panel"><span class="chip purple">REGISTRATION ${date(x.registrationDate)}</span><h3 style="margin-top:16px">${icons(x.name)} ${esc(x.name)}</h3><div class="muted small">Battle ${date(x.start)} – ${date(x.end-DAY)} · 00:00 UTC</div></div>`).join('')}</div><p class="note">Timings follow the bot’s configured event cycle. Gold Card Exchange days are separate from Gold Rush PvP; check Discord for announced card-trading windows.</p>`;
 tick();
}
function cardsPage(){const sets=[...new Set(Object.values(data.album.cards).map(c=>c.set))];$('page').innerHTML=heading('Autumn Tales','135 cards. Fifteen sets. A shopping list with consequences.','THE CARD ALBUM')+`<div class="filterrow"><input id="card-search" type="search" placeholder="Card number, name or set" aria-label="Search cards"><select id="card-stars" aria-label="Filter stars"><option value="">All stars</option>${[1,2,3,4,5].map(n=>`<option value="${n}">${n} stars</option>`).join('')}</select><select id="card-gold" aria-label="Filter Gold"><option value="">All cards</option><option value="gold">Gold only</option><option value="normal">Normal only</option></select><select id="card-set" aria-label="Filter set"><option value="">All sets</option>${sets.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="row between" style="margin-top:22px"><span class="small muted" id="card-count"></span><span class="chip gold">17 GOLD CARDS</span></div><div id="cards-grid" class="cards-grid"></div><div class="pagination"><button id="card-prev" class="button secondary">Previous</button><span id="card-page" class="small muted"></span><button id="card-next" class="button secondary">Next</button></div><p class="note">Looking for a trader? Use <span class="command">/findcard card:135</span> in Discord. That lookup shows who has or needs a card; player UIDs stay private.</p>`;
 for(const id of ['card-search','card-stars','card-gold','card-set'])$(id).addEventListener('input',()=>{cardPage=0;renderCards()});$('card-prev').onclick=()=>{cardPage--;renderCards()};$('card-next').onclick=()=>{cardPage++;renderCards()};renderCards();}
function renderCards(){const query=$('card-search').value.trim().toLowerCase().replace(/^#/,''),star=$('card-stars').value,gold=$('card-gold').value,set=$('card-set').value;const cards=Object.entries(data.album.cards).filter(([n,c])=>(!query||[n,c.name,c.set].some(s=>s.toLowerCase().includes(query)))&&(!star||c.stars===Number(star))&&(!gold||c.gold===(gold==='gold'))&&(!set||c.set===set));const pages=Math.max(1,Math.ceil(cards.length/24));cardPage=Math.max(0,Math.min(cardPage,pages-1));$('card-count').textContent=`${cards.length} cards found`;$('card-page').textContent=`${cardPage+1} / ${pages}`;$('card-prev').disabled=cardPage===0;$('card-next').disabled=cardPage===pages-1;$('cards-grid').innerHTML=cards.slice(cardPage*24,cardPage*24+24).map(([n,c])=>`<article class="card ${c.gold?'gold':''}"><div class="card-no"><span>#${n}</span>${c.gold?'<span class="chip gold">GOLD</span>':''}</div><h3>${esc(c.name)}</h3><div class="stars" aria-label="${c.stars} stars">${'★'.repeat(c.stars)}</div><div class="set">${esc(c.set)} · ${c.set_slot}</div></article>`).join('')||'<div class="empty">No cards found. The caravan checked twice.</div>'}
function exchangePage(){$('page').innerHTML=heading('Find your next trade.','The website helps you browse cards. The Discord bot connects the collectors.','CARD EXCHANGE')+`<div class="grid"><article class="panel guide"><h2>Post once. Replace completely.</h2><p>In the Card Trade channel, post the cards you want and the cards you can offer.</p><pre class="command">LF 112 118 135<br>FT 90 107 130</pre><p>A new valid post replaces your whole previous list. LF-only and FT-only are welcome. A 🃏 reaction means your list was saved.</p><div class="steps"><div class="step"><div class="step-num">1</div><div><h3>Set up privately</h3><p>Open <span class="command">/cardexchange</span> to save your CoC UID and choose Same Star, ±1 Star or Any Star.</p></div></div><div class="step"><div class="step-num">2</div><div><h3>Find a partner</h3><p>Direct Matches satisfy both players’ preferences. Possible Partners may still be useful—talk to them.</p></div></div><div class="step"><div class="step-num">3</div><div><h3>Trade in the game</h3><p>MilkRoad supplies introductions. Discord handles conversation. Clash of Critters handles the exchange.</p></div></div></div></article><article class="panel guide"><h2>Search without changing your list</h2><span class="command">/findcard card:135</span><p>Switch between <strong>Who Has It?</strong> and <strong>Who Needs It?</strong> privately. This search never changes or refreshes your list.</p><h3>Keep it current</h3><p>Normal cards stay active for 10 days; Gold cards for 7. Use <strong>Still Current</strong> to refresh the whole list. Stale leads remain separately available.</p><h3>Gold trading</h3><p>Gold cards trade only during announced Gold Exchange reset days. Discovery still works while trading is closed.</p><div class="chip gold">3 TOTAL EXCHANGES PER RESET DAY</div><p class="note">MilkRoad doesn’t know your remaining in-game attempts. Gold and normal trades share the same daily pool.</p><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><p>Player listings, preferences and UIDs stay in the Discord flow. This site has no connection to the player database.</p></article></div>`}
function commandsPage(){const groups=[['Events & timers',[['/event','Current regular event and PvP status.'],['/schedule','Upcoming events and battle registration days.'],['/when event:<name>','Find when a specific event returns.'],['/next','The next event.'],['/horde','Horde Invasion or settlement countdown.'],['/reset','Time until the 00:00 UTC daily reset.']]],['Pinball tools',[['/pinballs value:<PB> event:<optional>','Forward simulator. ×1 and re-fire ON initially; event overrides assume Gold Rush active.'],['/rods · /fertilizer · /pickaxes · /raft · /zobo','Target-resource estimators at ×1. Party OFF is machine only; Party ON starts at zero progress and includes returned PB.']]],['Card Exchange',[['/cardexchange','Private trade list, matches, UID, preferences and freshness controls.'],['/findcard card:<number>','Read-only Who Has / Who Needs discovery. Select a relevant partner to view their UID privately.'],['/goldtrade date:YYYY-MM-DD','Authorized hosts schedule a Gold Exchange UTC reset day, after confirmation.'],['/cleartrade','Authorized hosts reset the album board after confirmation. Saved UIDs and preferences remain.']]]];$('page').innerHTML=heading('The Discord command shelf.','The same MilkRoad tools, with the right command close at hand.','BOT FIELD GUIDE')+`<div class="grid">${groups.map(([title,list])=>`<article class="panel guide"><h2>${title}</h2>${list.map(([cmd,desc])=>`<div><span class="command">${esc(cmd)}</span><p>${esc(desc)}</p></div>`).join('')}</article>`).join('')}</div>`}
function tick(){const now=Date.now();$('clock').textContent=new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit',timeZone:'UTC'}).format(now)+' UTC';document.querySelectorAll('[data-countdown]').forEach(el=>el.textContent=countdown(Number(el.dataset.countdown)-now))}
function route(){serial++;currentCalculation=null;const key=location.hash.slice(1);const page=names[key]?key:'events';$('breadcrumb').textContent=names[page].toUpperCase();document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);a.setAttribute('aria-current',a.dataset.page===page?'page':'false')});({events:eventsPage,cards:cardsPage,exchange:exchangePage,commands:commandsPage,pinballs:pinballsPage,resources:resourcesPage})[page]();}
const interval=(q,coverage=75)=>{const lo=coverage===50?q.low50:q.low,hi=coverage===50?q.high50:q.high;return lo===hi?fmt(lo):`${fmt(lo)}–${fmt(hi)}`};
function rangePB(q){const u=q.high<100?1:q.high<10000?10:100;return{range:`${fmt(Math.max(1,Math.floor(q.low/u)*u))}–${fmt(Math.ceil(q.high/u)*u)}`,median:fmt(Math.max(1,Math.round(q.median/u)*u))}}
function row(label,q,compact=false,coverage=75){return `<div class="haul ${compact?'compact':''}"><span>${esc(label)}</span><strong>${interval(q,coverage)}</strong></div>`}
function toggleButton(id,checked,label){return `<div class="control-row"><label for="${id}">${label}</label><button type="button" id="${id}" class="switch" role="switch" aria-checked="${checked}" aria-label="${label}"><span></span></button></div>`}
function positiveInput(id){const n=Number($(id).value);if(!Number.isInteger(n)||n<1||n>10000000)throw Error('Enter a whole number from 1 to 10,000,000.');return n}
function context(){const override=$('calc-event').value;if(override)return{event:override,gold:true,label:'Gold Rush Active',icon:icons('Gold Rush #1'),override:true};const now=Date.now(),r=regularAt(now),p=pvpAt(now),can=p.name.startsWith('Gold Rush')||p.name==='Dune Rush',active=can&&!p.registration;return{event:r.name,gold:active,label:(can?p.name.replace(/ #\d+$/,''):'Energy Drink slot')+(active?' Active':p.registration&&can?' Registration':' Inactive'),icon:icons(can?p.name:'Gold Rush #1'),override:false}}
function pinballsPage(){const thisSerial=serial;$('page').innerHTML=heading('Pinballs in. Probability out.','Simulate a haul—not a promise. Party rewards and returned Pinballs are included.','THE PINBALL LAB')+`<div class="form-grid"><form id="calc-form" class="panel"><label for="calc-amount">Starting Pinballs</label><input id="calc-amount" type="number" min="1" max="10000000" step="1" value="18000" required><label for="calc-event">Regular event</label><select id="calc-event"><option value="">Current event · automatic</option>${Object.keys(PAYOUTS).map(n=>`<option>${n}</option>`).join('')}</select><div id="event-mode" class="note"></div><label for="calc-multiplier">Multiplier</label><select id="calc-multiplier"></select>${toggleButton('calc-refire',true,'Re-fire Party Pinballs')}<div class="note">Starts at zero Party progress. Only deterministic Party-track Pinballs are re-fired.</div><button class="button wide" id="calc-run">Simulate my haul</button><div id="calc-status" class="status" role="status" aria-live="polite"></div></form><div id="calc-result" class="panel" aria-live="polite"><div class="loading">The machine is considering its options…</div></div></div>`;let refire=true,lastRun=0;
 function options(){const amount=Number($('calc-amount').value),m=Number($('calc-multiplier').value)||1;$('calc-multiplier').innerHTML=unlocked(amount).map(x=>`<option value="${x}">×${x}</option>`).join('');$('calc-multiplier').value=unlocked(amount).includes(m)?m:1}
 function mode(){const c=context();$('event-mode').textContent=`${icons(c.event)} ${c.event} · ${c.icon} ${c.label}`+(c.override?' · event override assumes Gold Rush active.':'')}
 async function run(){const id=++lastRun;try{const amount=positiveInput('calc-amount'),c=context(),multiplier=Number($('calc-multiplier').value);$('calc-run').disabled=true;$('calc-status').textContent='Running 10,000 sessions…';const input={amount,event:c.event,gold:c.gold,multiplier,refire},result=await calculate('forward',input);if(thisSerial!==serial||id!==lastRun)return;currentCalculation={kind:'forward',input,result};const resource=PAYOUTS[c.event][0],order=[resource,'energy_drinks','pinballs','candy','catch_tatari','blue_card_packs','boost_x2_minutes'];let body=`<div class="result-head"><h2 style="margin:0">Estimated haul</h2><span class="chip live">75% RANGE</span></div><p class="small muted">${icons(c.event)} ${esc(c.event)} · ×${multiplier} · re-fire ${refire?'ON':'OFF'}</p>`;for(const key of order)if(result.haul[key])body+=row(LABELS[key],result.haul[key]);body+=`<div class="subheader">OTHER ACTIVITY · 50% RANGE</div>${row('⭐ Jackpot hits',result.jackpot,true,50)}${row('🎴 Card Hole hits',result.card_hole,true,50)}<details class="source-detail"><summary>Where the haul comes from</summary><p class="note">Resource ranges: P12.5–P87.5. Jackpot/Card Hole: P25–P75. Random Jackpot/Card Hole reward contents and EXP are excluded.</p>`;for(const key of [resource,'energy_drinks','candy'])if(result.haul[key]){body+=`<h3 style="margin-top:20px">${LABELS[key]}</h3>`;if(result.machine[key])body+=row('Machine',result.machine[key],true);if(result.party[key])body+=row('Tatari Party',result.party[key],true)}body+=`<h3 style="margin-top:20px">Pinballs</h3>${row('Party earned',result.earned,true)}${row('Additional firing',result.refired,true)}${row('Remaining / unspent',result.remaining,true)}${row('Party progress',result.progression,true)}</details>`;if(!c.gold&&data.party.direct_candy_per_x1===null)body+=`<p class="note">🍬 Direct-slot Candy is excluded: its ×1 payout is unconfirmed. Candy shown comes from Party rewards.</p>`;body+=`<p class="note">10,000 simulated sessions · each milestone collected once. RNG remains professionally unsupervised.</p>`;$('calc-result').innerHTML=body;$('calc-status').textContent='Ready · same inputs reuse the same estimate.'}catch(error){if(thisSerial===serial){$('calc-status').textContent=error.message;$('calc-result').innerHTML=`<div class="error">${esc(error.message)}</div>`}}finally{if(thisSerial===serial&&id===lastRun)$('calc-run').disabled=false}}
 $('calc-form').onsubmit=event=>{event.preventDefault();run()};$('calc-refire').onclick=()=>{refire=!refire;$('calc-refire').setAttribute('aria-checked',refire);run()};$('calc-amount').oninput=()=>{options();mode()};$('calc-event').onchange=()=>{mode();run()};$('calc-multiplier').onchange=run;options();mode();run();}
function resourcesPage(){const thisSerial=serial;$('page').innerHTML=heading('How many Pinballs?','Choose your target. The calculator works backwards from the machine and Party track.','RESOURCE ESTIMATES')+`<div class="form-grid"><form id="reverse-form" class="panel"><label for="resource-event">Resource</label><select id="resource-event">${Object.entries(PAYOUTS).map(([n,[key]])=>`<option value="${n}">${LABELS[key]}</option>`).join('')}</select><label for="resource-target">Target amount</label><input id="resource-target" type="number" min="1" max="10000000" step="1" value="6000" required>${toggleButton('resource-party',false,'Include Tatari Party')}<div id="party-explanation" class="note">Party OFF counts only direct machine output at ×1. It is independent of Gold Rush and Dune Rush.</div><button class="button wide" id="resource-run">Estimate starting Pinballs</button><div id="resource-status" class="status" role="status" aria-live="polite"></div></form><div id="resource-result" class="panel" aria-live="polite"><div class="loading">Consulting the machine…</div></div></div>`;let party=false,lastRun=0;
 async function run(){const id=++lastRun;try{const target=positiveInput('resource-target'),event=$('resource-event').value;$('resource-run').disabled=true;$('resource-status').textContent=party?'Solving the Party reward track…':'Sampling the machine’s waiting-time distribution…';const input={target,event,party},result=await calculate('reverse',input);if(serial!==thisSerial||id!==lastRun)return;currentCalculation={kind:'reverse',input,result};const rec=rangePB(result);$('resource-result').innerHTML=`<div class="result-head"><h2 style="margin:0">Starting Pinballs</h2><span class="chip live">75% RANGE</span></div><p class="small muted">Target: ${fmt(target)} ${LABELS[PAYOUTS[event][0]]} · ×1</p><div class="result-big">${rec.range}</div><div class="muted">Typical (median) · <strong style="color:var(--text)">${rec.median}</strong></div><div class="source-detail"><span class="chip ${party?'purple':''}">TATARI PARTY ${party?'ON':'OFF'}</span><p class="note">${party?'Starts from 0 Tatari Party progress. Includes resource rewards and recursively returned Pinballs. Uses the Gold-Rush-active Party table; cans are irrelevant to this target.':'Direct machine estimate at ×1. Uses the 22% event slot and its confirmed payout. Tatari Party excluded.'}</p></div><details class="source-detail"><summary>How this range is calculated</summary><p class="note">${party?'The same forward simulator evaluates candidate starting amounts. Numerical search finds the P12.5, median and P87.5 requirements using 2,048 sessions per candidate.':'10,000 draws from the waiting-time distribution for the required event hits. The central interval is P12.5–P87.5.'} Recommendations round outward for readability. They are estimates, not guarantees.</p></details>`;$('resource-status').textContent='Ready · 75% central expected range.'}catch(error){if(thisSerial===serial){$('resource-status').textContent=error.message;$('resource-result').innerHTML=`<div class="error">${esc(error.message)}</div>`}}finally{if(thisSerial===serial&&id===lastRun)$('resource-run').disabled=false}}
 $('reverse-form').onsubmit=event=>{event.preventDefault();run()};$('resource-event').onchange=run;$('resource-party').onclick=()=>{party=!party;$('resource-party').setAttribute('aria-checked',party);$('party-explanation').textContent=party?'Starts at zero Party progress. Uses the Gold-Rush-active Party table and re-fires deterministic Party PB.':'Party OFF counts only direct machine output at ×1. It is independent of Gold Rush and Dune Rush.';run()};run();}
try{const response=await fetch('data.json');if(!response.ok)throw Error('Game data could not be loaded.');data=await response.json();route();window.addEventListener('hashchange',route);setInterval(tick,1000);setInterval(()=>{if(!location.hash||location.hash==='#events')eventsPage()},60000);if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});register({name:'browse_coc_cards',description:'Open the card browser and filter by card number, name or set.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:100}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(typeof input?.query!=='string'||input.query.length>100)throw Error('Enter a search string of at most 100 characters.');history.replaceState(null,'','#cards');route();$('card-search').value=input.query;renderCards();return{summary:$('card-count').textContent}}});register({name:'simulate_coc_pinballs',description:'Run the forward Pinball simulator and show the result. Does not spend real game Pinballs.',inputSchema:{type:'object',properties:{amount:{type:'integer',minimum:1,maximum:10000000},event:{type:'string',enum:Object.keys(PAYOUTS)},multiplier:{type:'integer'},refire:{type:'boolean'}},required:['amount'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!Number.isInteger(input?.amount)||input.amount<1||input.amount>10000000)throw Error('Invalid amount.');const multiplier=input.multiplier??1;if(!unlocked(input.amount).includes(multiplier))throw Error('Multiplier is locked.');if(input.event&&!PAYOUTS[input.event])throw Error('Invalid event.');if(input.refire!==undefined&&typeof input.refire!=='boolean')throw Error('Invalid re-fire setting.');history.replaceState(null,'','#pinballs');route();$('calc-amount').value=input.amount;$('calc-amount').dispatchEvent(new Event('input'));$('calc-event').value=input.event||'';$('calc-multiplier').value=multiplier;if(input.refire===false)$('calc-refire').click();else $('calc-form').requestSubmit();for(let i=0;i<600;i++){if(currentCalculation?.kind==='forward'&&currentCalculation.input.amount===input.amount&&currentCalculation.input.multiplier===multiplier&&currentCalculation.input.refire===(input.refire??true)&&(!input.event||currentCalculation.input.event===input.event))return{resourceRanges:currentCalculation.result.haul,jackpot50:currentCalculation.result.jackpot};await new Promise(r=>setTimeout(r,100))}throw Error('Calculation timed out.')}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}}catch(error){$('page').innerHTML='<div class="error">'+esc(error.message)+'</div>'}
